(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x*0.015+t*0.2)*12 + Math.cos(y*0.02-t*0.15)*8;
  const warp2 = Math.cos(x*0.018-t*0.25)*10 + Math.sin(y*0.012+t*0.3)*14;
  const warp3 = Math.sin((x+y)*0.01+t*0.4)*6;
  const sx = x + warp1 + warp3, sy = y + warp2 + warp3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 5],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 2.1, 0],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*45, 0.075, 1.8, 1]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a1=Math.sin(d*f-t*sp), a2=Math.sin(d*f*1.3+t*sp*0.7+0.8);
    aS+=a1+a2*0.4; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin((d*f-t*sp)*(d2*f2-t*sp2))*0.015;
    }
  }
  const n=src.length, act=aS/(n*1.4), inh=iS/n;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*5-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.9))*0.3;
  const weave=Math.sin(sx*0.04+sy*0.025+t*0.8)*Math.cos(sx*0.03-sy*0.04+t*1.1)+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const micro=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.12;
  const cell=Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.5)*1.8)*0.25;
  const rd1=act-inh*0.65+weave*0.25+spiral+cross;
  const rd2=Math.tanh(rd1*1.8)*0.6+Math.tanh(rd1*3.5-0.3)*0.4;
  const blend=rd2*0.7+cell*0.2+micro*0.1;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,35,85],[18,70,120],[25,115,135],[50,160,145],
    [140,190,130],[210,195,80],[220,150,55],[200,95,55],[160,50,60],
    [100,25,65],[45,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const edge=Math.abs(rd2)>0.65?1.2:Math.abs(rd2)>0.3?1.05:0.95;
  const glow=Math.max(0,rd2)*0.15;
  const lum=0.85+glow;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge))|0
  ];
}
